import math

def f(k):
    return math.log(k) / k

def g(k):
    return math.log(k + 1) / k

def count_k(x):
    count = 0
    for k in range(1, 1000):
        if f(k) <= x < g(k):
            count += 1
    return count

max_n = 0
for i in range(1, 10000):
    x = i / 1000.0
    max_n = max(max_n, count_k(x))

print(f"Max n for x = i/1000: {max_n}")

import math

def h(k):
    return math.log(k) / k

def get_J(k):
    return (h(k), (k+1)/k * h(k+1))

def solve():
    intervals = []
    for k in range(1, 100):
        intervals.append(get_J(k))
        print(f"J_{k} = {intervals[-1]}")

    max_n = 0
    # Check all start points of the intervals
    for i, (start, end) in enumerate(intervals):
        count = 0
        for s, e in intervals:
            if s <= start < e:
                count += 1
        if count > max_n:
            max_n = count
            print(f"New max_n: {max_n} at start {start} of J_{i+1}")

    # Also check midpoints
    for i, (start, end) in enumerate(intervals):
        mid = (start + end) / 2
        count = 0
        for s, e in intervals:
            if s <= mid < e:
                count += 1
        if count > max_n:
            max_n = count
            print(f"New max_n: {max_n} at midpoint {mid} of J_{i+1}")

    print(f"Final max_n: {max_n}")

solve()

