import math

def h(k):
    return math.log(k) / k

def get_J(k):
    return (h(k), (k+1)/k * h(k+1))

def solve():
    intervals = []
    for k in range(1, 10000):
        intervals.append(get_J(k))

    max_n = 0
    # Use a more efficient way to find the max overlap
    events = []
    for i, (start, end) in enumerate(intervals):
        events.append((start, 1))
        events.append((end, -1))

    events.sort(key=lambda x: (x[0], -x[1]))

    current_n = 0
    for _, type in events:
        current_n += type
        if current_n > max_n:
            max_n = current_n

    print(f"Max n: {max_n}")

solve()
